// Written by hand (another tool may own such a name): it has no generator
// header, so it must be collected.
import 'package:grund/grund.dart' as grund;
import 'package:grund/annotations.dart';

/// A module in a file that only looks like generator output.
@Module()
final class HandwrittenModule extends grund.Module {
  /// Creates the module.
  const HandwrittenModule();
}
